'use strict';

/**
* LAPACK routine to solve a system of the form `(ca*A - w*D) X = s*B` or `(ca*A^T - w*D) X = s*B` with possible scaling and perturbation of `A`, where `A` is a 1 by 1 or 2 by 2 real matrix.
*
* @module @stdlib/lapack/base/dlaln2
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlaln2 = require( '@stdlib/lapack/base/dlaln2' );
*
* var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
* var B = new Float64Array( [ 1.0, 2.0 ] );
* var X = new Float64Array( 2 );
* var out = new Float64Array( 2 );
*
* var info = dlaln2( 'row-major', 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, out );
* // returns 0
*
* // X => <Float64Array>[ ~-0.087, ~1.391 ]
* // out => <Float64Array>[ 1.0, ~1.391 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlaln2 = require( '@stdlib/lapack/base/dlaln2' );
*
* var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
* var B = new Float64Array( [ 1.0, 2.0 ] );
* var X = new Float64Array( 2 );
* var out = new Float64Array( 2 );
*
* var info = dlaln2.ndarray( 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 1, 2, 0, 1.0, 1.0, B, 1, 2, 0, 0.5, 0.0, X, 1, 2, 0, out, 1, 0 );
* // returns 0
*
* // X => <Float64Array>[ ~-0.087, ~1.391 ]
* // out => <Float64Array>[ 1.0, ~1.391 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlaln2;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlaln2 = main;
} else {
	dlaln2 = tmp;
}


// EXPORTS //

module.exports = dlaln2;

// exports: { "ndarray": "dlaln2.ndarray" }
